/**
 * Layout oracle — geometry verification for the spin reference.
 *
 *   deno run -A oracles/layout/check.ts [--route <id>] [--theme <name>]
 *       [--width <px>] [--live <origin>] [--record <path>]
 *
 * Routes: table, avatar, avatar-group, join. Themes: default, console,
 * neobrut (light axis — the reference's default mode).
 *
 * Engine: **taffy**, via `npm:taffy-layout@3.0.0` (WebAssembly bindings for
 * the Rust layout engine). The stylesheet is generated by this repo's own
 * preset for the fixture's tokens — the same sheet the reference app builds —
 * and resolved the way a browser resolves it (variables against the chosen
 * theme, calc(), the cascade, inheritance). Taffy then computes every box;
 * no invariant reads a hand-measured number.
 *
 * Tradeoffs of the first cut (layout.ts carries the full list): taffy's
 * table layout is used directly, with `thead`/`tbody` flattened to rows;
 * text is measured with a per-character advance table instead of font
 * metrics, calibrated so `line-height: normal` is 1.5× the font size as the
 * reference measures it; sticky is checked as scroller-size-vs-content since
 * stickiness is paint, not geometry.
 *
 * Exit status is 1 when any invariant fails — the baseline is expected to
 * fail the sticky-table check, because the reference's preview panel is
 * exactly that cramped.
 */

import { descendants, type DomNode, parseHtml } from "./dom.ts";
import { buildSheet, resolveStyles, VIEWPORT } from "./css.ts";
import { fixtureHtml, ROUTES } from "./fixture.ts";
import { buildLayout, type LayoutResult } from "./layout.ts";
import { type CheckReport, checksFor } from "./invariants.ts";
import { type LiveReads, probeLive, readRecordedBaseline } from "./live.ts";

interface Options {
  route: string;
  theme: string;
  width: number;
  live: string | null;
  record: string | null;
}

const RECORDED_BASELINE = new URL("./baseline.json", import.meta.url).pathname;

function parseOptions(argv: readonly string[]): Options {
  const options: Options = {
    route: "table",
    theme: "default",
    width: VIEWPORT.width,
    live: null,
    record: null,
  };
  const flag = (name: string): string | null => {
    const index = argv.indexOf(name);
    return index >= 0 && index + 1 < argv.length ? argv[index + 1] : null;
  };
  const route = flag("--route");
  if (route !== null) options.route = route;
  const theme = flag("--theme");
  if (theme !== null) options.theme = theme;
  const width = flag("--width");
  if (width !== null && Number.isFinite(Number(width))) {
    options.width = Number(width);
  }
  options.live = flag("--live") ??
    (argv.includes("--live") ? "http://127.0.0.1:5199" : null);
  options.record = flag("--record");
  return options;
}

async function main(): Promise<number> {
  const options = parseOptions(Deno.args);
  const html = fixtureHtml(options.route);
  const sheet = await buildSheet(html);
  const root = parseHtml(html);
  const resolved = resolveStyles(root, sheet, options.theme);
  const vars = sheet.vars[options.theme];
  const layout = buildLayout(root, resolved, vars, options.width);
  try {
    const reports: CheckReport[] = checksFor(options.route).map((check) =>
      check({
        route: options.route,
        theme: options.theme,
        root,
        resolved,
        vars,
        layout,
        viewportWidth: options.width,
      })
    );
    printTaffyReport(options, reports);

    const routes = ROUTES.map((r) => r.id);
    const liveReads = await obtainLiveReads(options, routes, sheet.themes);
    if (liveReads !== null) {
      printLiveCrossCheck(options, liveReads, resolved, layout, root);
    }
    const failed = reports.filter((report) => !report.ok);
    console.log(
      `\n${reports.length - failed.length}/${reports.length} invariants hold` +
        (failed.length > 0
          ? ` — ${failed.map((f) => f.id).join(", ")} FAIL`
          : ""),
    );
    return failed.length > 0 ? 1 : 0;
  } finally {
    layout.dispose();
  }
}

async function obtainLiveReads(
  options: Options,
  routes: readonly string[],
  themes: readonly string[],
): Promise<LiveReads | null> {
  if (options.live !== null) {
    console.log(`\nlive probe: driving a browser against ${options.live} …`);
    const reads = await probeLive(options.live, routes, themes, {
      width: options.width,
      height: VIEWPORT.height,
    });
    if (reads === null) {
      console.log(
        "live probe: no browser or no answer — falling back to the recorded baseline",
      );
    } else {
      const target = options.record ?? RECORDED_BASELINE;
      await Deno.writeTextFile(target, JSON.stringify(reads, null, 1) + "\n");
      console.log(`live probe: wrote ${target}`);
      return reads;
    }
  }
  const recorded = await readRecordedBaseline(
    options.record ?? RECORDED_BASELINE,
  );
  if (recorded === null) return null;
  console.log(
    `\ncross-check: recorded browser reads from ${recorded.origin} ` +
      `(${recorded.measuredAt}, ${recorded.viewport.width}x${recorded.viewport.height})`,
  );
  return recorded;
}

function printTaffyReport(
  options: Options,
  reports: readonly CheckReport[],
): void {
  console.log(
    `spin layout oracle — route ${options.route}, theme ${options.theme}, ${options.width}px`,
  );
  console.log(
    "engine: taffy via npm:taffy-layout@3.0.0; CSS generated by @spin/preset\n",
  );
  for (const report of reports) {
    const mark = report.ok ? "PASS" : "FAIL";
    console.log(`[${mark}] ${report.id} — ${report.detail}`);
  }
}

/** Per-route comparison of the taffy numbers against the browser's reads. */
function printLiveCrossCheck(
  options: Options,
  reads: LiveReads,
  resolved: ReadonlyMap<DomNode, Record<string, string>>,
  layout: LayoutResult,
  root: DomNode,
): void {
  const reading = reads.byRoute[options.route]?.[options.theme];
  if (reading === undefined) {
    console.log("cross-check: no recorded read for this route and theme");
    return;
  }
  console.log(
    "source of each read: T = taffy (this run), B = browser (recorded)",
  );
  const lines: string[] = [];
  const round = (n: number): string => (Math.round(n * 100) / 100).toString();
  const agree = (t: number, b: number, tolerance: number): string =>
    Math.abs(t - b) <= tolerance ? "agree" : `DIFFER by ${round(t - b)}`;

  const oracleScrollers = descendants(root).filter((node) =>
    node.classes.includes("overflow-auto") &&
    descendants(node).some((d) => d.tag === "table")
  );
  for (const [index, sticky] of reading.sticky.entries()) {
    const scroller = oracleScrollers[index];
    if (scroller === undefined) continue;
    const table = descendants(scroller).find((d) => d.tag === "table")!;
    const rows = descendants(table).filter((d) =>
      d.tag === "tr" && d.parent?.tag !== "thead"
    );
    const header = descendants(table).find((d) => d.tag === "tr")!;
    const tScroller = layout.boxOf(scroller);
    const tHeader = layout.boxOf(header);
    const tTable = layout.boxOf(table);
    const firstRow = rows[0] === undefined ? 0 : layout.boxOf(rows[0]).height;
    lines.push(
      `sticky scroller  T ${
        round(tScroller.height)
      }px / B ${sticky.scrollerHeight}px — ${
        agree(tScroller.height, sticky.scrollerHeight, 1)
      }`,
    );
    lines.push(
      `sticky header    T ${
        round(tHeader.height)
      }px / B ${sticky.headerHeight}px — ${
        agree(tHeader.height, sticky.headerHeight, 1)
      }`,
    );
    lines.push(
      `first body row   T ${round(firstRow)}px / B ${
        sticky.rowHeights[0] ?? 0
      }px — ${agree(firstRow, sticky.rowHeights[0] ?? 0, 1)}`,
    );
    lines.push(
      `table content    T ${
        round(tTable.height)
      }px / B ${sticky.scrollHeight}px — ${
        agree(tTable.height, sticky.scrollHeight, 2)
      }`,
    );
  }
  const oracleJoins = descendants(root).filter((n) =>
    n.classes.includes("join")
  );
  for (const [index, join] of reading.joins.entries()) {
    const items = oracleJoins[index]?.children.filter((c) =>
      c.classes.includes("join-item")
    ) ?? [];
    const gaps = items.slice(1).map((item, i) => {
      const previous = layout.boxOf(items[i]);
      const current = layout.boxOf(item);
      return current.x - (previous.x + previous.width);
    });
    const same = gaps.length === join.gaps.length &&
      gaps.every((gap, i) =>
        Math.abs(gap - join.gaps[i]) <= 0.51
      );
    lines.push(
      `join ${index} seams      T ${gaps.map(round).join(", ")} / B ${
        join.gaps.map(round).join(", ")
      }px — ${same ? "agree" : "DIFFER"}`,
    );
  }
  const oracleAvatars = descendants(root).filter((n) =>
    n.classes.includes("avatar")
  );
  if (oracleAvatars.length > 0 && reading.avatars.length > 0) {
    const boxes = oracleAvatars.map((a) => layout.boxOf(a));
    lines.push(
      `avatars square   T ${
        boxes.map((b) => `${round(b.width)}x${round(b.height)}`).join(" ")
      } / B ${
        reading.avatars.map((a) => `${a.width}x${a.height}`).join(" ")
      } — ${
        boxes.every((b) => Math.abs(b.width - b.height) <= 0.51)
          ? "agree"
          : "DIFFER"
      }`,
    );
  }
  const oracleGroups = descendants(root).filter((n) =>
    n.classes.includes("avatar-group")
  );
  for (const [index, group] of reading.groups.entries()) {
    const kids = oracleGroups[index]?.children ?? [];
    const steps = kids.slice(1).map((kid, i) =>
      layout.boxOf(kid).x - layout.boxOf(kids[i]).x
    );
    // Taffy reports whole-pixel positions, so a step lands within a pixel
    // of the browser's sub-pixel one.
    const same = steps.length === group.steps.length &&
      steps.every((step, i) => Math.abs(step - group.steps[i]) <= 1);
    lines.push(
      `group ${index} steps     T ${steps.map(round).join(", ")} / B ${
        group.steps.map(round).join(", ")
      }px — ${same ? "agree" : "DIFFER"}`,
    );
  }
  if (reading.stripedOddBg !== null) {
    const striped = descendants(root).find((n) =>
      n.tag === "table" && n.classes.includes("striped")
    );
    const bodyRows = striped === undefined
      ? []
      : striped.children.flatMap((section) => section.children)
        .filter((tr) => tr.tag === "tr" && tr.parent?.tag === "tbody");
    const oddBg = bodyRows[0]?.children[0] === undefined
      ? "transparent"
      : resolved.get(bodyRows[0].children[0])?.["background-color"] ??
        "transparent";
    const evenBg = bodyRows[1]?.children[0] === undefined
      ? "transparent"
      : resolved.get(bodyRows[1].children[0])?.["background-color"] ??
        "transparent";
    lines.push(
      `striped odd bg   T ${oddBg} / B ${reading.stripedOddBg} — theme tokens, resolved`,
    );
    lines.push(
      `striped even bg  T ${evenBg} / B ${reading.stripedEvenBg} — theme tokens, resolved`,
    );
  }
  const rootBox = layout.boxOf(root);
  const browserFits = reading.docScrollWidth <= reading.docClientWidth;
  const oracleFits = rootBox.width <= options.width + 0.51;
  lines.push(
    `document fits    T ${oracleFits ? "yes" : "no"} (${
      round(rootBox.width)
    }px at ${options.width}px) / B ${
      browserFits ? "yes" : "no"
    } (scrollWidth ${reading.docScrollWidth} = clientWidth ${reading.docClientWidth}) — ${
      oracleFits === browserFits ? "agree" : "DIFFER"
    }`,
  );
  for (const line of lines) console.log(`  ${line}`);
}

const code = await main();
Deno.exit(code);
